```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' GROUP BY ALL ORDER BY p",
          "claim": "search's client span to geo rises from p50 0.37ms to 1577ms (p95 3016ms) in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE service_name='geo' AND attr_span_kind='Server' GROUP BY ALL ORDER BY p",
          "claim": "geo's own server spans stay flat at about 0.12-0.14ms p50, so the extra time lies on the search-to-geo connection."
        }
      ]
    },
    {
      "service": "rate",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, service_name, attr_k8s_pod_name pod, metric, count(*) n, avg(value) avgv, max(value) maxv FROM abnormal_metrics WHERE metric='container.cpu.usage' AND service_name='rate' GROUP BY ALL UNION ALL SELECT 'norm', service_name, attr_k8s_pod_name, metric, count(*), avg(value), max(value) FROM normal_metrics WHERE metric='container.cpu.usage' AND service_name='rate' GROUP BY ALL",
          "claim": "rate pod container CPU usage pins near 1.70 cores in the abnormal window versus about 0.008 normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE service_name='rate' AND attr_span_kind='Server' GROUP BY ALL ORDER BY p",
          "claim": "rate's GetRates server p50 rises from 0.12ms to 1.06ms while the CPU is pinned."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE (service_name='frontend' AND span_name='HTTP /hotels') OR (service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client') GROUP BY ALL ORDER BY service_name, span_name, p",
          "claim": "frontend's /hotels p50 jumps from 4.6ms to 1583ms, matching the slow search.Search/Nearby calls from frontend."
        }
      ]
    },
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM (SELECT 'norm' p, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client' GROUP BY ALL ORDER BY p",
          "claim": "search's client calls to rate slow modestly, p50 from 1.38ms to 1.73ms, while p95 stays near 2.5ms."
        }
      ]
    }
  ]
}
